  -- agg_uuc_phc_criteria
  ('agg_uuc_phc_criteria','id',1,'bigint',null,'Surrogate row identifier; carries no meaning.',null,'meta',false,null,false),
  ('agg_uuc_phc_criteria','dataset_id',2,'bigint',null,'Source dataset this row belongs to.',null,'key',true,'dim_dataset.dataset_id',true),
  ('agg_uuc_phc_criteria','geo_code',3,'text',null,'Geography this row counts.',null,'key',true,'dim_geo.geo_code',true),
  ('agg_uuc_phc_criteria','geo_level',4,'geo_level_enum','national|region|province|citymun','Level of the counted geography; there are no barangay rows.',null,'dimension',false,null,true),
  ('agg_uuc_phc_criteria','n_listed',5,'integer',null,'Barangays in this area on the 2025 UUC for PHC list - the denominator for routes (a), (b) and (c), but NOT for (d). Equal to agg_uuc_phc_counts.n_listed for the same geography; the migration aborts if they ever disagree.','count','measure',false,null,true),
  ('agg_uuc_phc_criteria','n_route_ip',6,'integer',null,'Criterion (a): listed barangays where at least 10 percent of the population are Indigenous Peoples. Overlaps the other three route counts - do not add them.','count','measure',false,null,true),
  ('agg_uuc_phc_criteria','n_route_conflict',7,'integer',null,'Criterion (b): listed barangays where armed conflict and displacement together reach 10 percent, OR the barangay is ELCAC-designated. The two shares are summed rather than read as the order literal "or" - that is what reproduces the source own Pass/Fail on every row it scored. Overlaps the other three route counts - do not add them.','count','measure',false,null,true),
  ('agg_uuc_phc_criteria','n_route_four_ps',8,'integer',null,'Criterion (c): listed barangays where at least 50 percent of the population are enrolled in 4Ps/CCT. Overlaps the other three route counts - do not add them.','count','measure',false,null,true),
  ('agg_uuc_phc_criteria','n_route_health',9,'integer',null,'Criterion (d): listed barangays whose source health_indicators score is 4 or more of 7, counted ONLY among barangays the comparison can be evaluated for. ITS DENOMINATOR IS n_health_evaluable, NEVER n_listed - dividing by n_listed understates the route by excluding nobody and counting everybody. Overlaps the other three route counts - do not add them.','count','measure',false,null,true),
  ('agg_uuc_phc_criteria','n_health_evaluable',10,'integer',null,'Listed barangays in this area whose provincial benchmarks can support criterion (d). Nationally 5,761 of 5,987: 226 barangays in 5 provinces carry benchmarks that are placeholders, zeroes, missing, or fractions, and criterion (d) cannot be evaluated for them at all. n_listed minus this is the excluded count. One further barangay, SUMISIP CENTRAL, counts as evaluable but carries no recorded criterion (d) score of its own, so route (d) does not count it. Their place on the list is not in doubt - the socio-economic test passes on any one of the four routes.','count','measure',false,null,true),
  -- agg_uuc_phc_indicator_dist
  ('agg_uuc_phc_indicator_dist','id',1,'bigint',null,'Surrogate row identifier; carries no meaning.',null,'meta',false,null,false),
  ('agg_uuc_phc_indicator_dist','dataset_id',2,'bigint',null,'Source dataset this row belongs to.',null,'key',true,'dim_dataset.dataset_id',true),
  ('agg_uuc_phc_indicator_dist','geo_code',3,'text',null,'Geography this distribution describes.',null,'key',true,'dim_geo.geo_code',true),
  ('agg_uuc_phc_indicator_dist','geo_level',4,'geo_level_enum','national|region|province|citymun','Level of the described geography; there are no barangay rows - at barangay grain the value itself is in fact_uuc_phc_indicators.',null,'dimension',false,null,true),
  ('agg_uuc_phc_indicator_dist','indicator',5,'text','physical_factor|ip_pop|armed_conf|idp|four_ps|imr|ufmr|fic|abr|pre_natal|sba|water','Which of the 12 cleaned indicators this row distributes, named by its fact_uuc_phc_indicators column.',null,'dimension',false,null,true),
  ('agg_uuc_phc_indicator_dist','value_max',6,'numeric',null,'Top of this indicator domain and the cap cleaning bounded it to: 100 for the nine coverage percentages, 1,000 for the three rates per 1,000. Bin width is value_max divided by 10.',null,'dimension',false,null,true),
  ('agg_uuc_phc_indicator_dist','n_listed',7,'integer',null,'Barangays in this area on the 2025 list - the population the bins account for. Equal to agg_uuc_phc_counts.n_listed for the same geography; the migration aborts if they ever disagree.','count','measure',false,null,true),
  ('agg_uuc_phc_indicator_dist','bin_counts',8,'integer[]',null,'Ten equal-width bins over 0 to value_max, index 1 being the lowest. The top bin closes inclusive so a capped value lands in it. Sums with n_missing to n_listed. DO NOT COMPUTE A MEAN, MEDIAN OR MIDPOINT ESTIMATE FROM THIS ARRAY - a bin midpoint weighted by these counts is an average, and averaging these indicators is what the whole dataset refuses, because the bounded values in the top bin are ceilings the source overshot rather than measurements. Report bins and counts.','count','dimension',false,null,true),
  ('agg_uuc_phc_indicator_dist','bin_capped',9,'integer[]',null,'How many of each bin barangays carry a value BOUNDED during cleaning rather than measured - a subset of bin_counts, and zero everywhere except the top bin by construction, since a bounded value equals value_max. Nationally 886 Water, 456 FIC, 208 Pre-natal, 30 SBA, 2 ABR, 1 IMR, 1 UFMR. A top-bin figure is not a statement about coverage until this count is stated beside it.','count','dimension',false,null,true),
  ('agg_uuc_phc_indicator_dist','n_missing',10,'integer',null,'Listed barangays here with no value recorded for this indicator. Nonzero for three indicators only: nationally 17 for ip_pop, 42 for armed_conf and 47 for idp. bin_counts plus this is n_listed.','count','measure',false,null,true),
  ('agg_uuc_phc_indicator_dist','provincial_ref',11,'numeric',null,'The provincial benchmark criterion (d) tests this indicator against. Populated ONLY on province and citymun rows of the seven health indicators - a region or the nation spans 87 different benchmarks and has no single one - and NULL for the five socio-economic indicators, which criterion (d) does not test. NOT USABLE ON ITS OWN: it is unreachable when it exceeds value_max (FIC reads 102.15 in Ilocos Sur and 100.96 in City of Butuan while every barangay FIC was capped at 100), and it is a placeholder when it is present but n_comparable is 0.',null,'measure',false,null,true),
  ('agg_uuc_phc_indicator_dist','n_comparable',12,'integer',null,'Listed barangays here whose criterion (d) comparison can actually be made for this indicator: a value is recorded, the province supplied a benchmark, the benchmark does not exceed value_max, and the province benchmark set is not a placeholder. Nationally 5,761 of 5,987 for six health indicators and 5,648 for FIC. Always 0 for the five socio-economic indicators.','count','measure',false,null,true),
  ('agg_uuc_phc_indicator_dist','n_worse',13,'integer',null,'Of n_comparable, how many perform worse than their province on this indicator - higher for the three rates per 1,000, lower for the four coverage percentages. REPORT IT AS A COUNT, never as a share: evaluable denominators differ between areas for data-quality reasons, so a percentage invites comparisons the data cannot carry.','count','measure',false,null,true),
  -- fact_uuc_phc_indicators
  ('fact_uuc_phc_indicators','id',1,'bigint',null,'Surrogate row identifier; carries no meaning.',null,'meta',false,null,false),
  ('fact_uuc_phc_indicators','dataset_id',2,'bigint',null,'Source dataset this row belongs to.',null,'key',true,'dim_dataset.dataset_id',true),
  ('fact_uuc_phc_indicators','geo_code',3,'text',null,'Listed barangay these values describe.',null,'key',true,'dim_geo.geo_code',true),
  ('fact_uuc_phc_indicators','physical_factor',4,'numeric',null,'Share of the barangay meeting the AO physical factors (distance, terrain, transport). Never below 25 - a barangay under that floor never entered the list, so this column has no low tail to find.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','ip_pop',5,'numeric',null,'Share of the barangay population who are Indigenous Peoples. 10 or more is one of the four qualifying routes.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','armed_conf',6,'numeric',null,'Share of the barangay population affected by armed conflict. Read with idp: criterion (b) is implemented as their sum, not as either alone.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','idp',7,'numeric',null,'Share of the barangay population who are internally displaced. Read with armed_conf - see that column.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','four_ps',8,'numeric',null,'Share of the barangay population who are 4Ps (Pantawid Pamilyang Pilipino Program) beneficiaries. 50 or more is one of the four qualifying routes.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','elcac_brgy',9,'boolean',null,'True where the barangay is ELCAC-designated as conflict-affected. Qualifies on its own, independent of the armed_conf and idp shares.',null,'dimension',false,null,true),
  ('fact_uuc_phc_indicators','imr',10,'numeric',null,'Infant mortality rate. Bounded at 1,000 during cleaning where the source recorded more; check capped_indicators before quoting this value.','per 1,000 live births','measure',false,null,true),
  ('fact_uuc_phc_indicators','ufmr',11,'numeric',null,'Under-five mortality rate. Bounded at 1,000 during cleaning where the source recorded more; check capped_indicators before quoting this value.','per 1,000 live births','measure',false,null,true),
  ('fact_uuc_phc_indicators','fic',12,'numeric',null,'Fully immunized child coverage. Bounded at 100 during cleaning where the source recorded more; check capped_indicators before quoting this value.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','abr',13,'numeric',null,'Adolescent birth rate. Bounded at 1,000 during cleaning where the source recorded more; check capped_indicators before quoting this value.','per 1,000 women aged 10-19','measure',false,null,true),
  ('fact_uuc_phc_indicators','pre_natal',14,'numeric',null,'Pre-natal care coverage. Bounded at 100 during cleaning where the source recorded more; check capped_indicators before quoting this value.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','sba',15,'numeric',null,'Skilled birth attendance coverage. Bounded at 100 during cleaning where the source recorded more; check capped_indicators before quoting this value.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','water',16,'numeric',null,'Access to safe water coverage. Bounded at 100 during cleaning where the source recorded more; check capped_indicators before quoting this value.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','imr_prov_ref',17,'numeric',null,'Provincial benchmark for infant mortality rate that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','per 1,000 live births','measure',false,null,true),
  ('fact_uuc_phc_indicators','ufmr_prov_ref',18,'numeric',null,'Provincial benchmark for under-five mortality rate that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','per 1,000 live births','measure',false,null,true),
  ('fact_uuc_phc_indicators','fic_prov_ref',19,'numeric',null,'Provincial benchmark for fully immunized child coverage that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','abr_prov_ref',20,'numeric',null,'Provincial benchmark for adolescent birth rate that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','per 1,000 women aged 10-19','measure',false,null,true),
  ('fact_uuc_phc_indicators','pre_natal_prov_ref',21,'numeric',null,'Provincial benchmark for pre-natal care coverage that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','sba_prov_ref',22,'numeric',null,'Provincial benchmark for skilled birth attendance coverage that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','water_prov_ref',23,'numeric',null,'Provincial benchmark for access to safe water coverage that criterion (d) compares this barangay against. NULL where the source supplied #N/A - 57 barangays in 2 provinces (Nueva Vizcaya, Zamboanga City). A further 169 barangays in 3 provinces carry a value that cannot support the comparison at all - a placeholder 1, a zero, or a fraction - so criterion (d) is not evaluable for 226 barangays in 5 provinces, not merely for the 57 with no value here. Test it as: the largest of this barangay seven benchmarks is null or at most 1. Never capped, unlike the barangay value beside it.','percent (0-100)','measure',false,null,true),
  ('fact_uuc_phc_indicators','capped_indicators',24,'text[]',null,'Which of THIS barangay values were bounded during cleaning, by column name (for example {water,fic}); empty for the 4,594 barangays whose values were all in range. 1,584 values across 1,397 barangays were recorded outside any possible range and bounded - coverage percentages at 100, rates at 1,000 - so 886 Water and 456 FIC values now read as exactly 100 with nothing else to distinguish them from genuine full coverage. A value named here is a ceiling, not a measurement: report it as bounded and its true figure as unknown, and never average or rank it.',null,'dimension',false,null,true),
  ('fact_uuc_phc_indicators','health_indicators',25,'smallint','0-7','NULL ON ONE ROW AND A NULL HERE IS NOT A ZERO - it means no score was ever recorded for that barangay. SUMISIP CENTRAL was added by the final-list alignment from a sheet that carries no score column, so route (d) does not count it; its listing rests on criterion (a). The source office own criterion (d) score: how many of the seven health assessments this barangay failed against its province. Loaded as supplied and NOT recomputable from the indicator and benchmark columns in this table - the source scored it before cleaning bounded the values, using Pass/Fail columns the extract drops. A recomputation from the published columns disagrees on 664 rows. 4 or more is the qualifying threshold, and it is the fourth of the four socio-economic routes. Not evaluable for 226 barangays in 5 provinces whose provincial benchmarks are placeholders, zeroes, missing or fractions; exclude those before quoting any share of this route.','count of 7','measure',false,null,true),
