  ('ref_uuc_phc_list','dataset_id',1,'bigint',null,'Source dataset this row belongs to.',null,'key',true,'dim_dataset.dataset_id',true),
  ('ref_uuc_phc_list','geo_code',2,'text',null,'PSGC code of the listed barangay, on the dashboard PSGC vintage.',null,'key',true,'dim_geo.geo_code',true),
  ('ref_uuc_phc_list','geo_name',3,'text',null,'Official PSA name of the BARANGAY - not of the city, province or region, which have their own name columns here.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','citymun_code',4,'text',null,'PSGC code of the city or municipality containing this barangay. Filter on this to scope to one town.',null,'key',true,'dim_geo.geo_code',true),
  ('ref_uuc_phc_list','citymun_name',5,'text',null,'Official PSA name of the city or municipality.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','province_code',6,'text',null,'PSGC code of the province. Filter on this to scope to one province.',null,'key',true,'dim_geo.geo_code',true),
  ('ref_uuc_phc_list','province_name',7,'text',null,'Official PSA name of the province.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','region_code',8,'text',null,'PSGC code of the region. Filter on this to scope to one region.',null,'key',true,'dim_geo.geo_code',true),
  ('ref_uuc_phc_list','region_name',9,'text',null,'Official PSA name of the region.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','source_geo_code',10,'text',null,'PSGC code exactly as the source workbook supplies it. Differs from geo_code for Sulu 87 barangays, which the source files under Region IX and dim_geo under BARMM. Provenance only - join on geo_code.',null,'key',false,null,true),
  ('ref_uuc_phc_list','source_region',11,'text',null,'Region name as the source workbook wrote it. PROVENANCE, NOT A DISPLAY NAME - use region_name.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','source_province',12,'text',null,'Province name as the source workbook wrote it. PROVENANCE, NOT A DISPLAY NAME - 9 of its 88 name groups do not match PSA names, which is why the geography is resolved by code instead.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','source_citymun',13,'text',null,'City or municipality name as the source workbook wrote it. PROVENANCE, NOT A DISPLAY NAME - use citymun_name.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','source_barangay',14,'text',null,'Barangay name as the source workbook wrote it. PROVENANCE, NOT A DISPLAY NAME - use geo_name.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','route_ip',15,'boolean','true|false','Criterion (a) of DOH AO No. 2020-0023: at least 10 percent of the population are Indigenous Peoples. THE FOUR ROUTE FLAGS OVERLAP - a barangay can qualify on several - so they never sum to the listed count and a remainder cannot be derived from them. A ROUTE FLAG IS FALSE WHERE THE VALUE BEHIND IT IS MISSING as well as where it is below the threshold - absence of evidence is counted as not qualifying, which is what makes these flags add up to the counts on /uuc-phc/criteria. Read ip_pop, armed_conf, idp and four_ps in the same row to tell the two apart.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','route_conflict',16,'boolean','true|false','Criterion (b): armed_conf plus idp reach 10 percent, or the barangay is ELCAC-designated. The two percentages are SUMMED rather than read as the order or - that is what reproduces the source own Pass/Fail on every row it scored. THE FOUR ROUTE FLAGS OVERLAP - a barangay can qualify on several - so they never sum to the listed count and a remainder cannot be derived from them. A ROUTE FLAG IS FALSE WHERE THE VALUE BEHIND IT IS MISSING as well as where it is below the threshold - absence of evidence is counted as not qualifying, which is what makes these flags add up to the counts on /uuc-phc/criteria. Read ip_pop, armed_conf, idp and four_ps in the same row to tell the two apart.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','route_four_ps',17,'boolean','true|false','Criterion (c): at least 50 percent of the population enrolled in 4Ps or CCT. THE FOUR ROUTE FLAGS OVERLAP - a barangay can qualify on several - so they never sum to the listed count and a remainder cannot be derived from them. A ROUTE FLAG IS FALSE WHERE THE VALUE BEHIND IT IS MISSING as well as where it is below the threshold - absence of evidence is counted as not qualifying, which is what makes these flags add up to the counts on /uuc-phc/criteria. Read ip_pop, armed_conf, idp and four_ps in the same row to tell the two apart.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','route_health',18,'boolean','true|false','Criterion (d): the source office own health_indicators score is at least 4 of 7. ONLY MEANINGFUL WHERE health_evaluable IS TRUE - false on a row where it is not means the comparison was never made, not that it failed. THE FOUR ROUTE FLAGS OVERLAP - a barangay can qualify on several - so they never sum to the listed count and a remainder cannot be derived from them.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','health_evaluable',19,'boolean','true|false','Whether criterion (d) can be evaluated for this barangay at all. False for 226 barangays in 5 provinces whose provincial benchmarks are placeholders, zeroes, fractions or missing. THE DENOMINATOR FOR route_health IS THE COUNT OF ROWS WHERE THIS IS TRUE, never the listed count.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','health_indicators',20,'smallint','0|1|2|3|4|5|6|7','The source office own criterion (d) score: how many of the seven health assessments this barangay failed against its province. LOADED AS SUPPLIED AND NOT RECOMPUTABLE from the indicator columns in this same row - the source scored it before cleaning bounded the values, so a recomputation disagrees on 664 barangays and would leave 98 listed barangays qualifying on no route at all, which the AO makes impossible.','count','measure',false,null,true),
  ('ref_uuc_phc_list','physical_factor',21,'numeric',null,'Percentage of the barangay sitios or puroks more than 60 minutes from a health facility. At least 25 in every row: below the AO floor a barangay never entered the list, so this is not a discriminating column within the list. Never capped.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','ip_pop',22,'numeric',null,'Percentage of the population who are Indigenous Peoples - what criterion (a) tests at 10. Null for 17 barangays the source left blank. Never capped.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','armed_conf',23,'numeric',null,'Percentage of the population affected by armed conflict. Read with idp: criterion (b) tests their SUM at 10, not either alone. Null for 42 barangays. Never capped.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','idp',24,'numeric',null,'Percentage of the population internally displaced. Read with armed_conf: criterion (b) tests their SUM at 10. Null for 47 barangays. Never capped.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','four_ps',25,'numeric',null,'Percentage of the population enrolled in 4Ps or CCT - what criterion (c) tests at 50. Never capped.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','elcac_brgy',26,'boolean','true|false','Designated a conflict-affected barangay under ELCAC. One of the two ways criterion (b) can be met.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','capped_indicators',27,'text[]',null,'WHICH OF THIS BARANGAY INDICATORS WERE BOUNDED DURING CLEANING, by column name; an empty array where none were. A named value is a ceiling the source overshot, not a measurement - the source recorded Water as high as 9,594 percent and FIC as 18,088, and those were bounded to 100 for coverage percentages or 1,000 for rates. 1,584 values across 1,397 barangays carry one. READ THIS BEFORE QUOTING imr, ufmr, abr, fic, pre_natal, sba OR water, AND NEVER AVERAGE THOSE COLUMNS without excluding or footnoting the rows named here.',null,'dimension',false,null,true),
  ('ref_uuc_phc_list','imr',28,'numeric',null,'Infant mortality, per 1,000 live births. Read capped_indicators on the same row before quoting this value: where it names this indicator the figure is a ceiling the cleaning bounded the source to, not a measurement. NEVER AVERAGE THIS COLUMN without excluding or footnoting those rows.','per 1,000 live births','measure',false,null,true),
  ('ref_uuc_phc_list','ufmr',29,'numeric',null,'Under-five mortality, per 1,000 live births. Read capped_indicators on the same row before quoting this value: where it names this indicator the figure is a ceiling the cleaning bounded the source to, not a measurement. NEVER AVERAGE THIS COLUMN without excluding or footnoting those rows.','per 1,000 live births','measure',false,null,true),
  ('ref_uuc_phc_list','abr',30,'numeric',null,'Adolescent birth rate, per 1,000 women aged 10 to 19. Read capped_indicators on the same row before quoting this value: where it names this indicator the figure is a ceiling the cleaning bounded the source to, not a measurement. NEVER AVERAGE THIS COLUMN without excluding or footnoting those rows.','per 1,000 women 10-19','measure',false,null,true),
  ('ref_uuc_phc_list','fic',31,'numeric',null,'Fully immunised children, percent. 456 readings were bounded to 100 and now read as exactly full coverage. Read capped_indicators on the same row before quoting this value: where it names this indicator the figure is a ceiling the cleaning bounded the source to, not a measurement. NEVER AVERAGE THIS COLUMN without excluding or footnoting those rows.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','pre_natal',32,'numeric',null,'Mothers with 4 or more pre-natal visits, percent. Read capped_indicators on the same row before quoting this value: where it names this indicator the figure is a ceiling the cleaning bounded the source to, not a measurement. NEVER AVERAGE THIS COLUMN without excluding or footnoting those rows.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','sba',33,'numeric',null,'Births with a skilled birth attendant, percent. Read capped_indicators on the same row before quoting this value: where it names this indicator the figure is a ceiling the cleaning bounded the source to, not a measurement. NEVER AVERAGE THIS COLUMN without excluding or footnoting those rows.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','water',34,'numeric',null,'Households with an improved water supply, percent. 886 readings were bounded to 100 and now read as exactly full coverage - 15 percent of the list. Read capped_indicators on the same row before quoting this value: where it names this indicator the figure is a ceiling the cleaning bounded the source to, not a measurement. NEVER AVERAGE THIS COLUMN without excluding or footnoting those rows.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','imr_prov_ref',35,'numeric',null,'Provincial infant mortality benchmark. The province figure criterion (d) compares the barangay against. NEVER capped - unlike the barangay values beside it.','per 1,000 live births','measure',false,null,true),
  ('ref_uuc_phc_list','ufmr_prov_ref',36,'numeric',null,'Provincial under-five mortality benchmark. The province figure criterion (d) compares the barangay against. NEVER capped - unlike the barangay values beside it.','per 1,000 live births','measure',false,null,true),
  ('ref_uuc_phc_list','abr_prov_ref',37,'numeric',null,'Provincial adolescent birth rate benchmark. The province figure criterion (d) compares the barangay against. NEVER capped - unlike the barangay values beside it.','per 1,000 women 10-19','measure',false,null,true),
  ('ref_uuc_phc_list','fic_prov_ref',38,'numeric',null,'Provincial fully-immunised-children benchmark. The province figure criterion (d) compares the barangay against. NEVER capped - unlike the barangay values beside it. That is why it reads 102.15 in Ilocos Sur and 100.96 in City of Butuan while every barangay fic was bounded to 100: no barangay there can reach it, so a worse-than-province verdict on fic would be true by construction for all 113 of them.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','pre_natal_prov_ref',39,'numeric',null,'Provincial 4-or-more pre-natal visits benchmark. The province figure criterion (d) compares the barangay against. NEVER capped - unlike the barangay values beside it.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','sba_prov_ref',40,'numeric',null,'Provincial skilled-birth-attendance benchmark. The province figure criterion (d) compares the barangay against. NEVER capped - unlike the barangay values beside it.','percent','measure',false,null,true),
  ('ref_uuc_phc_list','water_prov_ref',41,'numeric',null,'Provincial improved-water-supply benchmark. The province figure criterion (d) compares the barangay against. NEVER capped - unlike the barangay values beside it.','percent','measure',false,null,true),
  -- agg_bhw_by_uuc_status
  ('agg_bhw_by_uuc_status','id',1,'bigint',null,'Surrogate row identifier; carries no meaning.',null,'meta',false,null,false),
  ('agg_bhw_by_uuc_status','dataset_id',2,'bigint',null,'Source dataset this row belongs to. Keyed to uuc-phc-2025 because the row exists only because the list does - but the figures come from bhw-stepzero-2026 and bhw-2025, so a quote of them travels with those datasets vintages too.',null,'key',true,'dim_dataset.dataset_id',true),
  ('agg_bhw_by_uuc_status','geo_code',3,'text',null,'Geography this comparison describes.',null,'key',true,'dim_geo.geo_code',true),
  ('agg_bhw_by_uuc_status','geo_level',4,'geo_level_enum','national|region|province|citymun','Level of the described geography; there are no barangay rows - a barangay is entirely listed or entirely not, so one level down there is no split to draw.',null,'dimension',false,null,true),
  ('agg_bhw_by_uuc_status','n_barangays_listed',5,'integer',null,'Barangays in this area on the 2025 UUC for PHC list. Equal to agg_uuc_phc_counts.n_listed for the same geography, computed by a different path; the migration aborts if they disagree.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','n_barangays_other',6,'integer',null,'EVERY OTHER barangay in the area - NOT assessed and found adequate. The source workbook 9,395 assessed-but-unlisted barangays were never loaded, so that group does not exist here. Plus n_barangays_listed this is the area whole barangay count. Say all other barangays, never not listed, which a reader hears as assessed and passed.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','n_listed_with_data',7,'integer',null,'Listed barangays here carrying a StepZero row with a BHW count - the denominator the listed-side figures are built from, and the count the suppression rule tests. Equals n_barangays_listed today, since StepZero covers all 41,958 barangays.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','n_other_with_data',8,'integer',null,'Other barangays here carrying a StepZero row with a BHW count - the denominator the other-side figures are built from, and the count the suppression rule tests.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','n_listed_no_bhw',9,'integer',null,'Listed barangays here reporting zero BHWs. A real zero and a finding in its own right, never suppressed. Nationally 100 of 5,987.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','n_other_no_bhw',10,'integer',null,'Other barangays here reporting zero BHWs. A real zero, never suppressed. Nationally 945 of 35,967.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','listed_n_bhw',11,'integer',null,'StepZero total BHWs (registered plus registered and accredited plus non-registered) across this area listed barangays. Divide listed_households by this for households per BHW, the site operative workload measure - and always state listed_households divided by n_listed_with_data beside it, because listed barangays are smaller and that is most of any difference. NULL when listed_is_suppressed.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','other_n_bhw',12,'integer',null,'StepZero total BHWs across this area other barangays. NULL when other_is_suppressed. See listed_n_bhw.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','listed_households',13,'bigint',null,'Households in this area listed barangays, from StepZero - the denominator of households per BHW. NULL when listed_is_suppressed. LISTED BARANGAYS ARE SMALLER ON AVERAGE (about 0.58 times the households of the others nationally), so most of any households-per-BHW gap between the sides is barangay size rather than BHW deployment.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','other_households',14,'bigint',null,'Households in this area other barangays, from StepZero. NULL when other_is_suppressed. See listed_households on why barangay size, not deployment, drives most of the difference.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','listed_registered_universe',15,'integer',null,'StepZero registered plus registered-and-accredited BHWs on the listed side - the profiling-eligible base, and the ONLY denominator listed_n_profiled may be divided by. NULL when listed_is_suppressed.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','other_registered_universe',16,'integer',null,'StepZero registered plus registered-and-accredited BHWs on the other side - the profiling-eligible base, and the ONLY denominator other_n_profiled may be divided by. NULL when other_is_suppressed.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','listed_n_profiled',17,'integer',null,'Individually-profiled BHWs (agg_bhw_counts.n_total) on the listed side. CONTEXT, NOT AN INDICATOR: it exists so the difference in PROFILING COVERAGE between the two groups is visible, which is why this table splits the StepZero headcount rather than the per-person census. Never report it as BHW supply and never divide it by households. NULL when listed_is_suppressed.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','other_n_profiled',18,'integer',null,'Individually-profiled BHWs on the other side. CONTEXT, NOT AN INDICATOR - see listed_n_profiled. NULL when other_is_suppressed.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','unallocated_n_bhw',19,'integer',null,'BHWs in this area own published StepZero row that are in NEITHER group, because StepZero carries them above barangay grain only and there is no barangay to attach a list status to. 16 nationally, in 3 regions, and 0 everywhere else. listed_n_bhw plus other_n_bhw plus this equals agg_bhw_stepzero_counts.n_total_bhw exactly, which is asserted at load - so a split that omits it does not reconcile.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','unallocated_households',20,'bigint',null,'Households in this area own published StepZero row that are in neither group. 6,061 nationally, in 3 regions. See unallocated_n_bhw.','count','measure',false,null,true),
  ('agg_bhw_by_uuc_status','listed_is_suppressed',21,'boolean',null,'True when this area has between 1 and 4 listed barangays carrying data, and the listed-side measures were therefore nulled. READ IT BEFORE TREATING A NULL AS A ZERO. A PRESENTATION RULE, NOT A DISCLOSURE CONTROL: agg_bhw_stepzero_counts is public at barangay grain, so nothing here is secret - what it prevents is one, two or three barangays being rendered as a group statistic beside a group of hundreds.',null,'dimension',false,null,true),
  ('agg_bhw_by_uuc_status','other_is_suppressed',22,'boolean',null,'True when this area has between 1 and 4 other barangays carrying data, and the other-side measures were therefore nulled. See listed_is_suppressed.',null,'dimension',false,null,true),
  -- dim_legislative_district
  ('dim_legislative_district','district_code',1,'text',null,'Stable slug identifying the district, such as pampanga-2nd or abra-at-large. The key every other district table joins on.',null,'key',true,'dim_legislative_district.district_code',true),
  ('dim_legislative_district','congress_no',2,'smallint',null,'Which Congress this district composition belongs to. Every row currently loaded is 20 - always filter on it anyway, because a later Congress will add rows beside these rather than replace them.',null,'dimension',false,null,true),
  ('dim_legislative_district','district_name',3,'text',null,'The district''s name as its source article gives it, such as "Pampanga''s 2nd congressional district". Not always derivable from district_code: two districts carry a name whose wording differs from the slug.',null,'dimension',false,null,true),
  ('dim_legislative_district','ordinal',4,'smallint',null,'Which numbered district this is within its province or city (1st, 2nd, ...). NULL exactly when is_lone is true; there is no ordinal 0 and no ordinal for an at-large seat.',null,'dimension',false,null,true),
  ('dim_legislative_district','is_lone',5,'boolean',null,'True when the province or city elects a single representative at large, so the district and the whole LGU are the same area.',null,'dimension',false,null,true),
  ('dim_legislative_district','parent_geo_code',6,'text',null,'The province OR city this district sits in. A PROVINCE CODE FOR MOST ROWS AND A CITY CODE FOR OTHERS: PSGC files a highly urbanised city under its own province-level row, so a lone-district HUC such as Baguio points at a citymun code. Null on the two Taguig-Pateros rows, whose area spans two PSGC parents.',null,'key',true,'dim_geo.geo_code',true),
  ('dim_legislative_district','region_code',7,'text',null,'Region the district sits in, denormalized for filtering. Null on 3 of 250 rows where the source did not establish one (Calamba and the two Taguig-Pateros districts), so a region filter drops those three rather than mis-filing them.',null,'key',true,'dim_geo.geo_code',true),
  ('dim_legislative_district','wikidata_qid',8,'text',null,'Wikidata item for the district, used to cross-check that the parsed roster and the Wikidata roster name the same set of districts.',null,'meta',false,null,true),
  ('dim_legislative_district','psa_population',9,'integer',null,'The district population its own source article publishes. NOT A ROLL-UP OF THE MEMBER LGUs AND NEVER TO BE PRESENTED AS ONE - it is an independently published figure, which is exactly what makes it usable as a check against the summed members. THE CENSUS YEAR IS NOT STORED IN THIS TABLE and the articles quote different ones (195 say 2020, 34 say 2015, 21 say 2024), so two districts'' figures are not comparable to each other without it; the per-district year is in the QA report and docs/LEGISLATIVE_DISTRICTS.md. Five districts carry a figure that is stale against the LGU list printed beside it in the same article.','count','measure',false,null,true),
  ('dim_legislative_district','valid_from',10,'date',null,'First day this district composition applies - the 20th Congress term start on every current row.',null,'dimension',false,null,true),
  ('dim_legislative_district','valid_to',11,'date',null,'Last day this composition applies; null while current. Null on every current row.',null,'dimension',false,null,true),
  ('dim_legislative_district','source_kind',12,'text','wikidata|wikipedia|psa|manual|public_correction','What kind of source this row came from. wikipedia on every current row.',null,'dimension',false,null,true),
  ('dim_legislative_district','source_ref',13,'text',null,'The exact source, as page title and revision id: wikipedia:<article title>@<revid>. This is the row''s receipt - it names a version of a page that can still be opened and read.',null,'meta',false,null,true),
  ('dim_legislative_district','retrieved_at',14,'timestamptz',null,'When the source page was fetched. Distinct from as_of_date and valid_from, which are term boundaries rather than retrieval times.',null,'meta',false,null,true),
  ('dim_legislative_district','status',15,'text','auto|approved|rejected','Review state. auto means machine-derived and not yet reviewed by a person, which is every current row; rejected rows are hidden from public reads by the row-level policy.',null,'dimension',false,null,true),
  -- geo_district_map
  ('geo_district_map','id',1,'bigint',null,'Surrogate row identifier; carries no meaning.',null,'meta',false,null,false),
  ('geo_district_map','district_code',2,'text',null,'The district this place is assigned to.',null,'key',true,'dim_legislative_district.district_code',true),
  ('geo_district_map','geo_code',3,'text',null,'The place assigned. A city/municipality code OR a barangay code - read geo_level before joining or counting.',null,'key',true,'dim_geo.geo_code',true),
  ('geo_district_map','geo_level',4,'geo_level_enum','citymun|barangay','Grain of this row. citymun on 1,604 rows where a whole LGU sits in one district; barangay on 1,909 rows where a city is split across districts. A SPLIT CITY IS PRESENT ONLY THROUGH ITS BARANGAYS AND NEVER AS ITSELF, so a citymun-only filter silently drops every multi-district city.',null,'dimension',false,null,true),
  ('geo_district_map','match_method',5,'text','exact|disambiguated|crosswalk|manual_override|public_correction|whole_parent|independent_city|whole_citymun|psgc_identifier|barangay_roster','THE RULE THAT PLACED THIS ROW, and the first thing to read before trusting one. exact: the source named this place and the name resolved to exactly one dim_geo row. whole_parent: the district covers a whole province, so every LGU in it was expanded. whole_citymun: a caption named a city and the source did not enumerate its barangays. independent_city: a city outside the province that votes with it, read from the article''s lead sentence. psgc_identifier: the article printed a PSGC code. barangay_roster: the article''s barangay list matched a dim_geo city''s roster, used where a place had been renamed. manual_override: a documented hand decision. THERE IS NO FUZZY NAME-MATCHING VALUE AND THAT IS DELIBERATE - a place that resolved to nothing was left out, not approximated.',null,'dimension',false,null,true),
  ('geo_district_map','source_kind',6,'text','wikidata|wikipedia|psa|manual|public_correction','What kind of source placed this row. wikipedia on every current row.',null,'dimension',false,null,true),
  ('geo_district_map','source_ref',7,'text',null,'The exact source, as page title and revision id. 80 rows cite a per-city barangay list rather than the district''s own article, so this is NOT always the same string as the district''s source_ref.',null,'meta',false,null,true),
  ('geo_district_map','retrieved_at',8,'timestamptz',null,'When the source page was fetched.',null,'meta',false,null,true),
  ('geo_district_map','superseded_by',9,'bigint',null,'Row id that replaced this one when a correction was accepted; null while current.',null,'meta',false,null,false),
  ('geo_district_map','status',10,'text','auto|approved|rejected','Review state. auto means machine-derived and not yet reviewed by a person, which is every current row; rejected rows are hidden from public reads.',null,'dimension',false,null,true),
  ('geo_district_map','reviewed_at',11,'timestamptz',null,'When a person reviewed this row; null on every current row.',null,'meta',false,null,false),
  ('geo_district_map','reviewed_by',12,'text',null,'Who reviewed this row; null on every current row.',null,'meta',false,null,false),
  ('geo_district_map','review_note',13,'text',null,'Why a reviewer accepted or rejected this row; null on every current row.',null,'meta',false,null,false),
  ('geo_district_map','corroboration',14,'text','single_source|corroborated|conflict','Whether a second source has confirmed this assignment. single_source ON ALL 3,513 CURRENT ROWS - never describe one as verified. The intended second source, COMELEC''s precinct returns, is unreachable, so corroboration now arrives after publication through the public correction pipeline. A conflict row is one a second source contradicted and is withheld from the load entirely rather than shipped with a flag.',null,'dimension',false,null,true),
  ('geo_district_map','corroborating_source_ref',15,'text',null,'The second source that confirmed this row, where one did; null on every current row.',null,'meta',false,null,true),
  -- district_representative
  ('district_representative','id',1,'bigint',null,'Surrogate row identifier; carries no meaning.',null,'meta',false,null,false),
  ('district_representative','district_code',2,'text',null,'The district this person sits for.',null,'key',true,'dim_legislative_district.district_code',true),
  ('district_representative','congress_no',3,'smallint',null,'Which Congress. 20 on every current row.',null,'dimension',false,null,true),
  ('district_representative','full_name',4,'text',null,'The representative''s name AS THE SOURCE ARTICLE PRINTED IT - not reconciled against any official roster, so honorifics, nicknames, middle initials and suffixes vary between rows. Do not treat it as a canonical identifier and do not match people across datasets on it.',null,'dimension',false,null,true),
  ('district_representative','party',5,'text',null,'Political party. NULL ON EVERY CURRENT ROW: the source tables carry party inside a template this build does not parse, so null means not extracted, never independent or unaffiliated.',null,'dimension',false,null,true),
  ('district_representative','as_of',6,'date',null,'The date this naming applies from - the 20th Congress term start on every row. NOT the date the person took office and not the retrieval date.',null,'dimension',false,null,true),
  ('district_representative','source_kind',7,'text','wikidata|wikipedia|psa|manual|public_correction','What kind of source named this person. wikipedia on every current row.',null,'dimension',false,null,true),
  ('district_representative','source_ref',8,'text',null,'The exact source, as page title and revision id. Usually the province-level article rather than the district''s own.',null,'meta',false,null,true),
  ('district_representative','superseded_by',9,'bigint',null,'Row id that replaced this one; null while current.',null,'meta',false,null,false),
  ('district_representative','status',10,'text','auto|approved|rejected','Review state. auto on every current row; rejected rows are hidden from public reads.',null,'dimension',false,null,true)
) as c (
  table_name, column_name, ordinal, data_type, allowed_values,
  meaning, unit, role, is_join_key, joins_to, is_queryable
)
join dataset_registry r on r.table_name = c.table_name
on conflict (registry_id, column_name) do update set
  ordinal = excluded.ordinal,
  data_type = excluded.data_type,
  allowed_values = excluded.allowed_values,
  meaning = excluded.meaning,
  unit = excluded.unit,
  role = excluded.role,
  is_join_key = excluded.is_join_key,
  joins_to = excluded.joins_to,
  is_queryable = excluded.is_queryable,
  status = excluded.status;
